import { useMemo, useState, type FormEvent } from 'react';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { ArrowLeft, ArrowRight, ArrowUpRight, ArrowDownRight, Pencil, Award, Bell, Building2, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Coins, Filter, Gift, Heart, Leaf, MapPin, Minus, PackageCheck, Plus, Recycle, Search, ShieldCheck, SlidersHorizontal, Sparkles, Target, Truck, UserRound, Users, X } from 'lucide-react';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { collectionPoints, levelNames, monthlyImpact, rewards, type Appointment, type Campaign, type CollectionPoint, type EquipmentItem, type UserRole } from '../data';
import { Button, DemoBadge, Eyebrow, MetricCard, Modal, StatusPill, SuccessLine } from '../components/ui';
import MapPanel from '../components/MapPanel';
import { useStore } from '../store';

const statusTone = (s: Appointment['status']) => s === 'Concluído' ? 'green' : s === 'Cancelado' ? 'red' : s === 'Em coleta' ? 'blue' : s === 'Confirmado' ? 'green' : 'orange';
const deviceOptions = ['Smartphone', 'Notebook', 'Computador', 'Tablet', 'Monitor', 'Cabos', 'Carregadores', 'Teclado', 'Impressora', 'Pilhas', 'Baterias', 'Mouses'];

function pointDistance(point: CollectionPoint, origin: { lat: number; lng: number } | null) {
  if (!origin) return point.distance;
  const radians = (degrees: number) => degrees * Math.PI / 180;
  const dLat = radians(point.lat - origin.lat);
  const dLng = radians(point.lng - origin.lng);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(radians(origin.lat)) * Math.cos(radians(point.lat)) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
export function PointsPage() {
  const [query, setQuery] = useState('');
  const [material, setMaterial] = useState('Todos os materiais');
  const [category, setCategory] = useState('Todos os tipos');
  const [distanceLimit, setDistanceLimit] = useState('Qualquer distância');
  const [accessibility, setAccessibility] = useState('Todos os acessos');
  const [availability, setAvailability] = useState('Qualquer horário');
  const [selectedId, setSelectedId] = useState(collectionPoints[0].id);
  const [origin, setOrigin] = useState<{ lat: number; lng: number } | null>(null);
  const [locationMessage, setLocationMessage] = useState('');
  const [locating, setLocating] = useState(false);
  const categories = useMemo(() => Array.from(new Set(collectionPoints.map(point => point.category))), []);
  const points = useMemo(() => collectionPoints.filter(point => {
    const q = query.toLowerCase().trim();
    const matchesQuery = !q || [point.name, point.category, point.neighborhood, point.city, point.cep, point.address, ...point.materials].some(v => v.toLowerCase().includes(q));
    const matchesMaterial = material === 'Todos os materiais' || point.materials.some(m => m.toLowerCase().includes(material.toLowerCase()));
    const matchesCategory = category === 'Todos os tipos' || point.category === category;
    const maximum = distanceLimit === 'Qualquer distância' ? Infinity : Number(distanceLimit);
    const matchesDistance = pointDistance(point, origin) <= maximum;
    const matchesAccess = accessibility !== 'Acessível' || /sem degraus|acess|rampa|nível|térreo/i.test(point.access);
    const matchesAvailability = availability !== 'Aberto hoje' || point.availability.includes('Aberto');
    return matchesQuery && matchesMaterial && matchesCategory && matchesDistance && matchesAccess && matchesAvailability;
  }).map(point => ({ ...point, distance: pointDistance(point, origin) })).sort((a, b) => a.distance - b.distance), [query, material, category, distanceLimit, accessibility, availability, origin]);
  const locate = () => {
    if (!navigator.geolocation) { setLocationMessage('Este navegador não oferece geolocalização. Distâncias estimadas continuam disponíveis.'); return; }
    setLocating(true); setLocationMessage('Aguardando permissão de localização…');
    navigator.geolocation.getCurrentPosition(position => {
      setOrigin({ lat: position.coords.latitude, lng: position.coords.longitude });
      setLocationMessage('Distâncias recalculadas neste navegador; sua localização não é salva. Os pontos continuam sendo fictícios.');
      setLocating(false);
    }, () => { setLocationMessage('Localização não autorizada ou indisponível. Exibindo distâncias demonstrativas.'); setLocating(false); }, { enableHighAccuracy: false, maximumAge: 300000, timeout: 8000 });
  };
  return <div className="points-page"><div className="page-toolbar"><div className="toolbar-search"><Search size={16} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Nome, bairro, cidade ou material..." aria-label="Buscar ponto de coleta" /><kbd>⌘ K</kbd></div><label className="filter-select"><Filter size={15} /><select value={material} onChange={e => setMaterial(e.target.value)} aria-label="Filtrar por material"><option>Todos os materiais</option>{['Celulares', 'Notebooks', 'Computadores', 'Cabos', 'Pilhas', 'Baterias', 'Monitores'].map(m => <option key={m}>{m}</option>)}</select><ChevronDown size={14} /></label><label className="filter-select"><MapPin size={14} /><select value={category} onChange={e => setCategory(e.target.value)} aria-label="Filtrar por tipo de ponto"><option>Todos os tipos</option>{categories.map(item => <option key={item}>{item}</option>)}</select><ChevronDown size={14} /></label><label className="filter-select"><select value={distanceLimit} onChange={e => setDistanceLimit(e.target.value)} aria-label="Filtrar pela distância máxima"><option>Qualquer distância</option><option value="5">Até 5 km</option><option value="10">Até 10 km</option><option value="20">Até 20 km</option></select><ChevronDown size={14} /></label><label className="filter-select"><select value={accessibility} onChange={e => setAccessibility(e.target.value)} aria-label="Filtrar por acessibilidade"><option>Todos os acessos</option><option>Acessível</option></select><ChevronDown size={14} /></label><label className="filter-select"><select value={availability} onChange={e => setAvailability(e.target.value)} aria-label="Filtrar disponibilidade"><option>Qualquer horário</option><option>Aberto hoje</option></select><ChevronDown size={14} /></label></div>
    <div className="points-summary"><div><strong>{points.length}</strong> pontos encontrados <span>em Grande São Paulo</span></div><DemoBadge /><button className="points-locate" onClick={locate} disabled={locating}><MapPin size={14} />{locating ? 'Localizando…' : 'Usar minha localização'}</button></div>{locationMessage && <div className="point-location-message" role="status">{locationMessage}</div>}
    <div className="points-explorer"><div className="point-list">{points.map(point => <PointCard key={point.id} point={point} selected={selectedId === point.id} onClick={() => setSelectedId(point.id)} />)}{points.length === 0 && <div className="empty-state"><Search size={22} /><strong>Nenhum ponto encontrado</strong><span>Tente outro termo ou ajuste os filtros.</span></div>}</div><MapPanel points={points} selectedId={selectedId} className="points-map" /></div>
    <div className="point-demo-note"><ShieldCheck size={15} /> Os endereços e contatos são fictícios e servem apenas para explorar a demonstração. Distâncias e acessibilidade também são indicativas; confirme informações diretamente com os operadores antes de se deslocar.</div>
  </div>;
}
function PointCard({ point, selected, onClick }: { point: CollectionPoint; selected: boolean; onClick: () => void }) {
  return <article className={`point-card ${selected ? 'point-card-selected' : ''}`} onClick={onClick} onKeyDown={e => { if (e.key === 'Enter') onClick(); }} tabIndex={0} role="button" aria-pressed={selected}><div className="point-card-top"><span className="point-category-icon"><MapPin size={16} /></span><span className="point-distance">{point.distance.toFixed(1)} km</span></div><h3>{point.name}</h3><span className="point-category">{point.category}</span><p className="point-address">{point.address} · {point.neighborhood}</p><div className="point-card-meta"><span><Clock3 size={13} />{point.hours}</span><StatusPill tone="green">{point.availability}</StatusPill></div><div className="material-chips">{point.materials.slice(0, 4).map(m => <span key={m}>{m}</span>)}{point.materials.length > 4 && <span>+{point.materials.length - 4}</span>}</div><div className="point-card-actions"><Link to={`/app/pontos-de-coleta/${point.id}`} onClick={e => e.stopPropagation()}>Detalhes <ArrowRight size={14} /></Link><a href={`https://www.openstreetmap.org/directions?from=&to=${point.lat}%2C${point.lng}`} target="_blank" rel="noreferrer" onClick={e => e.stopPropagation()}>Como chegar <ArrowUpRight size={13} /></a></div></article>;
}

export function PointDetailPage() {
  const { id = '' } = useParams();
  const point = collectionPoints.find(p => p.id === id) ?? collectionPoints[0];
  return <div className="detail-page"><Link className="back-link" to="/app/pontos-de-coleta"><ArrowLeft size={14} />Voltar aos pontos</Link><div className="detail-top-card"><div className="detail-point-icon"><MapPin size={24} /></div><div className="detail-point-title"><Eyebrow>{point.category} · Registro demonstrativo</Eyebrow><h2>{point.name}</h2><p>{point.address}, {point.neighborhood}, {point.city}</p></div><StatusPill tone="green">{point.availability}</StatusPill></div><div className="detail-columns"><div className="detail-main"><section className="panel detail-panel"><h3>Materiais recebidos</h3><p>Confirme a disponibilidade antes do deslocamento.</p><div className="material-chips detail-chips">{point.materials.map(m => <span key={m}><Check size={12} />{m}</span>)}</div><div className="detail-info-grid"><div><span>Horário</span><strong><Clock3 size={15} />{point.hours}</strong></div><div><span>Contato demonstrativo</span><strong>{point.phone}</strong></div><div><span>Acessibilidade</span><strong>{point.access}</strong></div><div><span>Distância estimada</span><strong>{point.distance.toFixed(1)} km</strong></div></div><div className="guide-note"><strong>Orientação</strong><p>{point.note}</p></div><div className="point-demo-note"><ShieldCheck size={15} /> Endereço e telefone fictícios. Verifique dados locais antes de sair.</div></section><section className="panel detail-panel"><h3>Localização aproximada</h3><MapPanel points={[point]} selectedId={point.id} className="detail-map" /></section></div><aside className="panel detail-aside"><div className="detail-aside-icon"><Recycle size={22} /></div><h3>Pronto para dar um novo destino?</h3><p>Organize seus equipamentos e escolha como realizar o descarte.</p><Button to="/app/agendamentos/novo" className="full-width">Agendar descarte <ArrowRight size={15} /></Button><Button to="/app/agendamentos/novo" variant="secondary" className="full-width">Planejar entrega</Button><span className="detail-aside-foot"><ShieldCheck size={13} />A confirmação será demonstrativa.</span></aside></div></div>;
}

export function AppointmentsPage() {
  const { state, cancelAppointment } = useStore();
  const [filter, setFilter] = useState('Todos');
  const [cancelId, setCancelId] = useState<string | null>(null);
  const list = useMemo(() => state.appointments.filter(a => filter === 'Todos' || a.status === filter), [state.appointments, filter]);
  const confirmCancel = () => { if (cancelId) cancelAppointment(cancelId); setCancelId(null); };
  return <div className="appointments-page"><div className="page-section-toolbar"><div><h2>Seus descartes em um só lugar.</h2><p>Consulte horários, protocolos e status dos agendamentos demonstrativos.</p></div><Button to="/app/agendamentos/novo"><Plus size={16} />Novo agendamento</Button></div><div className="tab-row">{['Todos', 'Solicitado', 'Confirmado', 'Em coleta', 'Concluído', 'Cancelado'].map(s => <button key={s} className={filter === s ? 'tab-active' : ''} onClick={() => setFilter(s)}>{s}{s === 'Todos' && <span>{state.appointments.length}</span>}</button>)}</div><div className="appointment-table-wrap"><table className="data-table"><thead><tr><th>PROTOCOLO</th><th>EQUIPAMENTOS</th><th>DATA E HORÁRIO</th><th>MODALIDADE</th><th>STATUS</th><th /></tr></thead><tbody>{list.map(a => { const point = collectionPoints.find(p => p.id === a.pointId); return <tr key={a.id}><td><Link className="protocol-link" to={`/app/agendamentos/${a.id}`}>{a.protocol}</Link><small>Criado em {new Date(`${a.createdAt}T12:00:00`).toLocaleDateString('pt-BR')}</small></td><td><strong>{a.equipment.map(x => `${x.quantity}× ${x.kind}`).join(', ')}</strong><small>{a.estimatedWeight.toFixed(1)} kg estimados</small></td><td><strong>{new Date(`${a.date}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' })}</strong><small>às {a.time}</small></td><td><span className="table-mode">{a.mode === 'Entrega em ponto' ? <MapPin size={14} /> : <Truck size={14} />}{a.mode}</span><small>{point?.name ?? a.address ?? 'Local a definir'}</small></td><td><StatusPill tone={statusTone(a.status)}>{a.status}</StatusPill></td><td><div className="table-actions"><Link to={`/app/agendamentos/${a.id}`} aria-label="Ver agendamento"><ChevronRight size={17} /></Link>{a.status !== 'Concluído' && a.status !== 'Cancelado' && <button onClick={() => setCancelId(a.id)} aria-label="Cancelar agendamento"><X size={15} /></button>}</div></td></tr>; })}</tbody></table>{list.length === 0 && <div className="empty-state"><CalendarDays size={25} /><strong>Nenhum agendamento nesta categoria.</strong><Button to="/app/agendamentos/novo" size="sm">Agendar agora</Button></div>}</div><div className="inline-demo-note"><ShieldCheck size={14} /> Agendamentos salvos localmente neste navegador. Pontos só são concedidos depois de uma validação demonstrativa.</div><Modal open={!!cancelId} title="Cancelar agendamento?" onClose={() => setCancelId(null)}><div className="confirm-modal"><p>O pedido ficará marcado como cancelado nesta demonstração. Esta ação não pode ser desfeita.</p><div className="modal-actions"><Button variant="secondary" onClick={() => setCancelId(null)}>Manter agendamento</Button><Button variant="dark" onClick={confirmCancel}>Confirmar cancelamento</Button></div></div></Modal></div>;
}

export function NewAppointmentPage() {
  const [step, setStep] = useState(0);
  const [mode, setMode] = useState<Appointment['mode']>('Entrega em ponto');
  const [pointId, setPointId] = useState(collectionPoints[0].id);
  const [date, setDate] = useState(() => new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10));
  const [time, setTime] = useState('10:30');
  const [address, setAddress] = useState({ cep: '', street: '', number: '', complement: '', neighborhood: '', city: 'São Paulo', state: 'SP' });
  const [items, setItems] = useState<EquipmentItem[]>([{ id: `eq-${Date.now()}`, kind: 'Smartphone', quantity: 1, condition: 'Em funcionamento', weight: 0.35, note: '' }]);
  const [message, setMessage] = useState('');
  const { createAppointment } = useStore();
  const navigate = useNavigate();
  const updateItem = (id: string, data: Partial<EquipmentItem>) => setItems(old => old.map(it => it.id === id ? { ...it, ...data } : it));
  const addItem = () => setItems(old => [...old, { id: `eq-${Date.now()}`, kind: 'Notebook', quantity: 1, condition: 'Usado', weight: 2.2, note: '' }]);
  const removeItem = (id: string) => setItems(old => old.length > 1 ? old.filter(it => it.id !== id) : old);
  const estimated = items.reduce((sum, item) => sum + item.quantity * item.weight, 0);
  const next = () => {
    if (step === 0 && items.some(it => !it.kind || it.quantity < 1)) return setMessage('Confira tipo e quantidade de cada equipamento.');
    if (step === 2 && mode === 'Coleta no endereço' && (!address.cep || !address.street || !address.number || !address.neighborhood || !address.city || !address.state)) return setMessage('Preencha CEP, rua, número, bairro, cidade e estado.');
    if (step === 2 && mode === 'Entrega em ponto' && !pointId) return setMessage('Selecione um ponto de coleta demonstrativo.');
    if (step === 3 && (!date || !time || new Date(`${date}T${time}:00`).getTime() <= Date.now())) return setMessage('Selecione uma data e um horário futuros disponíveis.');
    setMessage(''); setStep(s => Math.min(5, s + 1));
  };
  const submit = () => {
    if (!date || !time || new Date(`${date}T${time}:00`).getTime() <= Date.now()) return setMessage('Escolha uma data e um horário futuros.');
    const fullAddress = mode === 'Coleta no endereço' ? `${address.street}, ${address.number}${address.complement ? ` · ${address.complement}` : ''}, ${address.neighborhood}, ${address.city} - ${address.state}, ${address.cep}` : undefined;
    const id = createAppointment({ date, time, mode, pointId: mode === 'Entrega em ponto' ? pointId : undefined, address: fullAddress, equipment: items });
    navigate(`/app/agendamentos/${id}`);
  };
  const steps = ['Equipamentos', 'Modalidade', 'Localização', 'Data e horário', 'Revisão', 'Confirmação'];
  return <div className="wizard-page"><div className="wizard-heading"><Link to="/app/agendamentos" className="back-link"><ArrowLeft size={14} />Agendamentos</Link><h2>Vamos planejar um novo ciclo.</h2><p>Conte para nós o que você quer destinar.</p></div><div className="wizard-progress"><div className="wizard-steps">{steps.map((name, i) => <div className={`wizard-step ${i === step ? 'current' : ''} ${i < step ? 'completed' : ''}`} key={name}><span>{i < step ? <Check size={14} /> : `0${i + 1}`}</span><small>{name}</small></div>)}</div><div className="wizard-track"><span style={{ width: `${(step / (steps.length - 1)) * 100}%` }} /></div></div><div className="wizard-card">
    {step === 0 && <div className="wizard-content"><div className="wizard-title"><span className="wizard-icon"><PackageCheck size={18} /></span><div><h3>Quais equipamentos você vai destinar?</h3><p>Você pode incluir vários itens; o peso é uma estimativa inicial.</p></div></div>{items.map((item, i) => <div className="equipment-form-card" key={item.id}><div className="equipment-form-head"><strong>Equipamento {String(i + 1).padStart(2, '0')}</strong>{items.length > 1 && <button className="icon-button" onClick={() => removeItem(item.id)} aria-label="Remover equipamento"><X size={16} /></button>}</div><div className="form-grid form-grid-four"><label className="form-label">Tipo<select className="form-control" value={item.kind} onChange={e => updateItem(item.id, { kind: e.target.value })}>{deviceOptions.map(d => <option key={d}>{d}</option>)}</select></label><label className="form-label">Quantidade<div className="quantity-input"><button onClick={() => updateItem(item.id, { quantity: Math.max(1, item.quantity - 1) })} aria-label="Diminuir"><Minus size={14} /></button><input type="number" min="1" value={item.quantity} onChange={e => updateItem(item.id, { quantity: Math.max(1, Number(e.target.value)) })} /><button onClick={() => updateItem(item.id, { quantity: item.quantity + 1 })} aria-label="Aumentar"><Plus size={14} /></button></div></label><label className="form-label">Estado<select className="form-control" value={item.condition} onChange={e => updateItem(item.id, { condition: e.target.value })}><option>Em funcionamento</option><option>Usado</option><option>Danificado</option><option>Sem funcionamento</option></select></label><label className="form-label">Peso estimado (kg)<input className="form-control" type="number" min="0.1" step="0.1" value={item.weight} onChange={e => updateItem(item.id, { weight: Math.max(0.1, Number(e.target.value)) })} /></label></div><label className="form-label">Observação (opcional)<input className="form-control" placeholder="Ex.: tela quebrada, bateria ausente..." value={item.note} onChange={e => updateItem(item.id, { note: e.target.value })} /></label></div>)}<button className="add-equipment" onClick={addItem}><Plus size={15} />Adicionar outro equipamento</button><div className="weight-preview"><ScaleIcon /><span>Peso total estimado<strong>{estimated.toFixed(1)} kg</strong></span><small>Estimativa não validada</small></div></div>}
    {step === 1 && <div className="wizard-content"><div className="wizard-title"><span className="wizard-icon"><Truck size={18} /></span><div><h3>Como prefere fazer a destinação?</h3><p>Escolha entre entregar em um ponto ou solicitar coleta.</p></div></div><div className="choice-grid"><button className={`choice-card ${mode === 'Entrega em ponto' ? 'choice-selected' : ''}`} onClick={() => setMode('Entrega em ponto')}><span className="choice-icon"><MapPin size={22} /></span><span className="choice-radio" /><strong>Entrega em ponto</strong><p>Leve seus equipamentos a um local parceiro que recebe essa categoria.</p><small>Você verá endereços e horários</small></button><button className={`choice-card ${mode === 'Coleta no endereço' ? 'choice-selected' : ''}`} onClick={() => setMode('Coleta no endereço')}><span className="choice-icon choice-green"><Truck size={22} /></span><span className="choice-radio" /><strong>Coleta no endereço</strong><p>Informe o endereço para uma solicitação de coleta demonstrativa.</p><small>Disponibilidade sujeita à confirmação</small></button></div><div className="inline-demo-note"><CircleHelp size={15} />Nenhum transporte real é solicitado nesta demonstração.</div></div>}
    {step === 2 && <div className="wizard-content"><div className="wizard-title"><span className="wizard-icon"><MapPin size={18} /></span><div><h3>{mode === 'Entrega em ponto' ? 'Escolha o ponto de entrega.' : 'Onde podemos encontrar você?'}</h3><p>{mode === 'Entrega em ponto' ? 'Selecione um local demonstrativo para o seu planejamento.' : 'Este endereço será salvo apenas neste navegador.'}</p></div></div>{mode === 'Entrega em ponto' ? <div className="point-choice-list">{collectionPoints.slice(0, 5).map(p => <button className={`point-choice ${pointId === p.id ? 'point-choice-selected' : ''}`} key={p.id} onClick={() => setPointId(p.id)}><span className="point-choice-radio" /><span className="point-choice-main"><strong>{p.name}</strong><small>{p.address} · {p.neighborhood}</small><span className="material-chips">{p.materials.slice(0, 3).map(m => <i key={m}>{m}</i>)}</span></span><span className="point-choice-distance">{p.distance.toFixed(1)} km</span></button>)}</div> : <div className="form-grid"><label className="form-label">CEP<input className="form-control" placeholder="00000-000" value={address.cep} onChange={e => setAddress({ ...address, cep: e.target.value })} /></label><label className="form-label form-span-2">Rua<input className="form-control" placeholder="Nome da rua" value={address.street} onChange={e => setAddress({ ...address, street: e.target.value })} /></label><label className="form-label">Número<input className="form-control" placeholder="Nº" value={address.number} onChange={e => setAddress({ ...address, number: e.target.value })} /></label><label className="form-label">Complemento<input className="form-control" placeholder="Apto, bloco..." value={address.complement} onChange={e => setAddress({ ...address, complement: e.target.value })} /></label><label className="form-label">Bairro<input className="form-control" value={address.neighborhood} onChange={e => setAddress({ ...address, neighborhood: e.target.value })} /></label><label className="form-label">Cidade<input className="form-control" value={address.city} onChange={e => setAddress({ ...address, city: e.target.value })} /></label><label className="form-label">Estado<input className="form-control" maxLength={2} value={address.state} onChange={e => setAddress({ ...address, state: e.target.value.toUpperCase() })} /></label></div>}</div>}
    {step === 3 && <div className="wizard-content"><div className="wizard-title"><span className="wizard-icon"><CalendarDays size={18} /></span><div><h3>Quando seria melhor?</h3><p>Selecione uma data futura e uma janela de horário demonstrativa.</p></div></div><div className="schedule-grid"><label className="form-label">Data<input className="form-control" type="date" min={new Date().toISOString().slice(0, 10)} value={date} onChange={e => setDate(e.target.value)} /></label><div className="form-label">Horários disponíveis<div className="time-slot-grid">{['09:00', '10:30', '13:00', '14:30', '16:00'].map(slot => <button key={slot} className={`time-slot ${time === slot ? 'time-slot-selected' : ''}`} onClick={() => setTime(slot)}>{slot}</button>)}</div></div></div><div className="schedule-info"><Clock3 size={15} />Horários exibidos como exemplo. Confirmação operacional não é enviada.</div></div>}
    {step === 4 && <div className="wizard-content review-content"><div className="wizard-title"><span className="wizard-icon"><ShieldCheck size={18} /></span><div><h3>Confira os detalhes.</h3><p>Seu protocolo ficará salvo localmente nesta demonstração.</p></div></div><div className="review-summary"><div className="review-row"><span>Equipamentos</span><strong>{items.reduce((s, i) => s + i.quantity, 0)} item(ns) · {estimated.toFixed(1)} kg estimados</strong></div>{items.map(i => <div className="review-item" key={i.id}><PackageCheck size={14} /><span>{i.quantity}× {i.kind}</span><small>{i.condition} · {i.weight.toFixed(1)} kg/un</small></div>)}<div className="review-row"><span>Modalidade</span><strong>{mode}</strong></div><div className="review-row"><span>Local</span><strong>{mode === 'Entrega em ponto' ? collectionPoints.find(p => p.id === pointId)?.name : address.street ? `${address.street}, ${address.number}, ${address.city}` : 'Endereço informado'}</strong></div><div className="review-row"><span>Data e horário</span><strong>{new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' })} · {time}</strong></div></div><div className="no-points-notice"><Coins size={15} />EcoPoints só são concedidos quando o descarte é validado pelo painel demonstrativo.</div></div>}
    {step === 5 && <div className="wizard-content final-confirmation"><div className="wizard-title"><span className="wizard-icon"><CheckCircle2 size={18} /></span><div><h3>Revise e confirme sua solicitação.</h3><p>Nenhuma coleta real será acionada; o registro ficará salvo neste navegador.</p></div></div><div className="review-summary"><div className="review-row"><span>Modalidade</span><strong>{mode}</strong></div><div className="review-row"><span>Equipamentos</span><strong>{items.reduce((sum, item) => sum + item.quantity, 0)} unidades · {estimated.toFixed(1)} kg estimados</strong></div><div className="review-row"><span>Data e horário</span><strong>{new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' })} · {time}</strong></div><div className="review-row"><span>Destino</span><strong>{mode === 'Entrega em ponto' ? collectionPoints.find(point => point.id === pointId)?.name : `${address.street}, ${address.number}, ${address.city}`}</strong></div></div><div className="no-points-notice"><ShieldCheck size={15} />A solicitação receberá um protocolo demonstrativo. Pontos só serão creditados após a validação administrativa.</div></div>}
    {message && <div className="form-error-message"><CircleHelp size={15} />{message}</div>}
    <div className="wizard-actions">{step > 0 ? <Button variant="secondary" onClick={() => { setMessage(''); setStep(s => s - 1); }}><ArrowLeft size={15} />Voltar</Button> : <span />}{step < 5 ? <Button onClick={next}>Continuar <ArrowRight size={15} /></Button> : <Button onClick={submit}>Confirmar agendamento <Check size={15} /></Button>}</div>
  </div><div className="wizard-bottom-note"><ShieldCheck size={14} /> Este fluxo é demonstrativo. Não há coleta real nem comunicação com operadores.</div></div>;
}
function ScaleIcon() { return <span className="scale-icon">kg</span>; }

export function AppointmentDetailPage() {
  const { id = '' } = useParams();
  const { state, cancelAppointment } = useStore();
  const [cancelOpen, setCancelOpen] = useState(false);
  const appointment = state.appointments.find(a => a.id === id);
  if (!appointment) return <div className="empty-state"><CalendarDays size={25} /><strong>Agendamento não encontrado.</strong><Button to="/app/agendamentos">Voltar aos agendamentos</Button></div>;
  const point = collectionPoints.find(p => p.id === appointment.pointId);
  const stage = appointment.status === 'Concluído' ? 3 : appointment.status === 'Cancelado' ? -1 : appointment.status === 'Em coleta' ? 2 : appointment.status === 'Confirmado' ? 1 : 0;
  return <div className="detail-page"><Link className="back-link" to="/app/agendamentos"><ArrowLeft size={14} />Agendamentos</Link><section className="panel appointment-detail-card"><div className="appointment-detail-head"><div><Eyebrow>Protocolo demonstrativo</Eyebrow><h2>{appointment.protocol}</h2><p>Criado em {new Date(`${appointment.createdAt}T12:00:00`).toLocaleDateString('pt-BR')}</p></div><StatusPill tone={statusTone(appointment.status)}>{appointment.status}</StatusPill></div>{appointment.status !== 'Cancelado' && <div className="timeline">{['Solicitado', 'Confirmado', 'Em coleta', 'Concluído'].map((s, i) => <div className={`timeline-step ${stage >= i ? 'timeline-done' : ''} ${stage === i ? 'timeline-current' : ''}`} key={s}><span>{stage > i ? <Check size={14} /> : i + 1}</span><small>{s}</small>{i < 3 && <i />}</div>)}</div>}<div className="appointment-detail-grid"><div><span>Modalidade</span><strong>{appointment.mode}</strong></div><div><span>Data e horário</span><strong>{new Date(`${appointment.date}T12:00:00`).toLocaleDateString('pt-BR')} · {appointment.time}</strong></div><div><span>Local</span><strong>{point?.name ?? appointment.address ?? 'A confirmar'}</strong></div><div><span>Peso estimado</span><strong>{appointment.estimatedWeight.toFixed(1)} kg</strong></div></div><h3>Equipamentos</h3><div className="equipment-detail-list">{appointment.equipment.map(item => <div key={item.id}><span className="equipment-detail-icon"><PackageCheck size={16} /></span><strong>{item.quantity}× {item.kind}</strong><span>{item.condition}</span><small>{(item.weight * item.quantity).toFixed(1)} kg</small></div>)}</div><div className="no-points-notice"><Coins size={15} />Pontos não são atribuídos antes da validação. Esta tela apresenta dados demonstrativos locais.</div>{appointment.status !== 'Cancelado' && appointment.status !== 'Concluído' && <div className="appointment-detail-actions"><Button variant="secondary" onClick={() => setCancelOpen(true)}>Cancelar agendamento</Button><Button to="/app/pontos-de-coleta">Ver ponto de coleta <MapPin size={14} /></Button></div>}</section><Modal open={cancelOpen} onClose={() => setCancelOpen(false)} title="Cancelar agendamento?"><div className="confirm-modal"><p>O status será atualizado nesta demonstração local.</p><div className="modal-actions"><Button variant="secondary" onClick={() => setCancelOpen(false)}>Voltar</Button><Button variant="dark" onClick={() => { cancelAppointment(appointment.id); setCancelOpen(false); }}>Confirmar cancelamento</Button></div></div></Modal></div>;
}

export function RewardsPage() {
  const { state, redeem } = useStore();
  const [reward, setReward] = useState<(typeof rewards)[number] | null>(null);
  const [toast, setToast] = useState('');
  const [rewardCategory, setRewardCategory] = useState('Todas categorias');
  const [rankingType, setRankingType] = useState<'individual' | 'institutional'>('individual');
  const level = Math.min(Math.floor(state.pointBalance / 500), levelNames.length - 1);
  const progress = Math.min(100, (state.pointBalance % 500) / 5);
  const confirmRedeem = () => { if (!reward) return; const receipt = redeem(reward.cost, reward.name); setToast(receipt ? `Resgate demonstrativo registrado. Comprovante local: ${receipt}.` : 'Saldo insuficiente para este resgate.'); setReward(null); window.setTimeout(() => setToast(''), 5200); };
  const achievements = [{ name: 'Primeiro descarte', detail: 'Você já começou uma nova jornada.', done: true, icon: '✳' }, { name: '10 dispositivos', detail: 'Destine 10 equipamentos corretamente.', done: false, icon: '⌘' }, { name: '10 kg destinados', detail: 'Ajude a completar a próxima meta.', done: false, icon: '↗' }, { name: 'Participação em campanha', detail: 'Participe de uma ação comunitária.', done: true, icon: '◎' }, { name: 'Diversidade de materiais', detail: 'Destine 4 categorias diferentes.', done: false, icon: '✺' }];
  return <div className="rewards-page"><section className="rewards-hero"><div className="rewards-hero-copy"><span className="rewards-hero-kicker"><Sparkles size={14} />ECONOMIA CIRCULAR COM RECONHECIMENTO</span><h2>Seu impacto merece<br /><em>ser reconhecido.</em></h2><p>EcoPoints celebram as contribuições validadas e incentivam novos ciclos sustentáveis.</p><div className="rewards-level"><span className="level-icon"><Award size={19} /></span><div><small>SEU NÍVEL ATUAL</small><strong>{levelNames[level]}</strong></div><span className="level-dots">● ● ● ◦ ◦</span></div></div><div className="points-wallet"><div className="wallet-top"><span>SEU SALDO</span><span className="wallet-eco"><Leaf size={13} /> ECOPOINTS</span></div><div className="wallet-value">{state.pointBalance.toLocaleString('pt-BR')}<span> pts</span></div><div className="wallet-card-foot"><span><span className="wallet-dot" />Saldo de demonstração</span><span>05 NOV · 2026</span></div><div className="wallet-decoration">✳</div></div></section><div className="rewards-goal"><div className="goal-mini-icon"><Target size={17} /></div><div className="goal-mini-copy"><strong>Próximo nível: {levelNames[level + 1] ?? levelNames[level]}</strong><small>Seu progresso é calculado sobre registros validados nesta demonstração.</small></div><div className="goal-mini-progress"><div><span>Progresso</span><strong>{Math.round(progress)}%</strong></div><div className="progress-track"><span style={{ width: `${progress}%` }} /></div><small>{500 - (state.pointBalance % 500)} EcoPoints até a próxima faixa</small></div></div>
    <section className="panel rewards-catalog"><div className="panel-head"><div><span className="panel-eyebrow">CATÁLOGO DE RECONHECIMENTO</span><h2>Escolha seu próximo incentivo.</h2><p>Itens ilustrativos; o resgate não representa benefício comercial real.</p></div><label className="catalog-filter"><Filter size={14} /><select aria-label="Filtrar recompensas por categoria" value={rewardCategory} onChange={e => setRewardCategory(e.target.value)}><option>Todas categorias</option>{Array.from(new Set(rewards.map(r => r.category))).map(category => <option key={category}>{category}</option>)}</select><ChevronDown size={12} /></label></div><div className="reward-grid">{rewards.filter(r => rewardCategory === 'Todas categorias' || r.category === rewardCategory).map((r, i) => <article className="reward-card" key={r.id}><div className={`reward-art reward-art-${i}`}><span className="reward-art-icon">{i === 0 ? <Truck size={29} /> : i === 1 ? <Leaf size={30} /> : i === 2 ? <Recycle size={30} /> : <Sparkles size={30} />}</span><span className="reward-art-index">0{i + 1}</span></div><span className="reward-category">{r.category}</span><h3>{r.name}</h3><p>{r.description}</p><div className="reward-card-foot"><span><Coins size={15} />{r.cost} pts</span><button disabled={!r.available} onClick={() => setReward(r)}>Resgatar <ArrowRight size={14} /></button></div></article>)}</div></section>
    <section className="panel points-history-panel"><div className="panel-head"><div><span className="panel-eyebrow">EXTRATO ECOPOINTS</span><h2>Seu histórico de pontos.</h2><p>Créditos de descarte validado e resgates demonstrativos.</p></div><span className="demo-badge"><span className="demo-dot" />Somente neste navegador</span></div><div className="point-history-list">{state.pointHistory.map(transaction => <div className="point-history-row" key={transaction.id}><span className={`point-history-icon ${transaction.kind === 'credit' ? 'point-history-credit' : 'point-history-debit'}`}>{transaction.kind === 'credit' ? <ArrowUpRight size={15} /> : <ArrowDownRight size={15} />}</span><div className="point-history-copy"><strong>{transaction.description}</strong><span>{transaction.detail}</span><small>{new Date(`${transaction.date}T12:00:00`).toLocaleDateString('pt-BR')}</small></div><div className="point-history-amount"><strong className={transaction.kind === 'credit' ? 'amount-credit' : 'amount-debit'}>{transaction.amount > 0 ? '+' : ''}{transaction.amount.toLocaleString('pt-BR')} pts</strong><small>Saldo: {transaction.balance.toLocaleString('pt-BR')} pts</small></div></div>)}{state.pointHistory.length === 0 && <div className="empty-state">Ainda não há transações nesta demonstração.</div>}</div></section>
    <div className="achievement-layout"><section className="panel achievement-panel"><div className="panel-head"><div><span className="panel-eyebrow">CONQUISTAS</span><h2>Uma jornada feita de etapas.</h2></div><span className="achievement-count">{achievements.filter(a => a.done).length} / {achievements.length}</span></div><div className="achievement-list">{achievements.map((a, i) => <div className={`achievement-row ${a.done ? 'achievement-done' : ''}`} key={a.name}><span className={`achievement-symbol achievement-symbol-${i}`}>{a.done ? <Check size={15} /> : a.icon}</span><div><strong>{a.name}</strong><span>{a.detail}</span></div>{a.done ? <StatusPill tone="green">Concluída</StatusPill> : <span className="achievement-locked">Em progresso</span>}</div>)}</div></section><section className="panel ranking-panel"><div className="panel-head"><div><span className="panel-eyebrow">COMUNIDADE</span><h2>Ranking da jornada</h2></div><UsersIcon /></div><div className="ranking-tabs"><button className={rankingType === 'individual' ? 'selected' : ''} onClick={() => setRankingType('individual')}>Individual</button><button className={rankingType === 'institutional' ? 'selected' : ''} onClick={() => setRankingType('institutional')}>Institucional</button></div>{(rankingType === 'individual' ? [['AM', 'Ana Martins', '2.480', 'EcoHero'], ['JP', 'João Pereira', '1.960', 'Guardião'], ['LC', 'Luiza Costa', '1.420', 'Exploradora'], ['VC', 'Victor Cardoso', '980', 'Explorador']] : [['TC', 'Tech Conecta', '12.800', 'Empresa'], ['EH', 'Escola Horizonte', '9.640', 'Escola'], ['CL', 'Coletivo Circular', '7.220', 'Comunidade'], ['PE', 'Parceiros Eco', '5.480', 'Empresa']]).map((p, i) => <div className={`ranking-row ${i === 0 ? 'ranking-me' : ''}`} key={p[0]}><span className="ranking-place">0{i + 1}</span><span className={`ranking-avatar rank-${i}`}>{p[0]}</span><div><strong>{p[1]}{i === 0 && rankingType === 'individual' && <small>VOCÊ</small>}</strong><span>{p[3]}</span></div><b>{p[2]} <small>pts</small></b></div>)}<div className="ranking-disclaimer">Nomes e posições são fictícios e demonstrativos.</div></section></div>
    <Modal open={!!reward} onClose={() => setReward(null)} title="Confirmar resgate demonstrativo"><div className="redeem-modal"><div className="redeem-icon"><Gift size={23} /></div><h3>{reward?.name}</h3><p>{reward?.description}</p><div className="redeem-summary"><span>Custo do resgate</span><strong><Coins size={15} />{reward?.cost} EcoPoints</strong></div><div className="redeem-summary"><span>Saldo depois do resgate</span><strong>{Math.max(0, state.pointBalance - (reward?.cost ?? 0)).toLocaleString('pt-BR')} pts</strong></div><p className="redeem-small">Este resgate fica registrado apenas no armazenamento local desta demonstração.</p><div className="modal-actions"><Button variant="secondary" onClick={() => setReward(null)}>Cancelar</Button><Button disabled={state.pointBalance < (reward?.cost ?? 0)} onClick={confirmRedeem}>Confirmar resgate <ArrowRight size={14} /></Button></div></div></Modal>{toast && <div role="status" className="toast-message"><CheckCircle2 size={16} />{toast}<button onClick={() => setToast('')} aria-label="Fechar aviso"><X size={14} /></button></div>}</div>;
}
function UsersIcon() { return <span className="panel-head-icon"><Heart size={18} /></span>; }

export function ImpactPage() {
  const [period, setPeriod] = useState('6 meses');
  const selectedMapId = collectionPoints[0].id;
  const { state } = useStore();
  const totalKg = (state.records.reduce((sum, r) => sum + r.weight, 0) + 12.8).toFixed(1);
  const chartData = period === '7 dias' ? [{ month: 'Seg', kg: 1 }, { month: 'Ter', kg: 1.6 }, { month: 'Qua', kg: 1.2 }, { month: 'Qui', kg: 2.3 }, { month: 'Sex', kg: 1.8 }, { month: 'Sáb', kg: 2.6 }, { month: 'Dom', kg: 2.1 }] : period === '30 dias' ? [{ month: '1ª sem.', kg: 7 }, { month: '2ª sem.', kg: 11 }, { month: '3ª sem.', kg: 8 }, { month: '4ª sem.', kg: 14 }] : period === '90 dias' ? [{ month: 'Mês 1', kg: 21 }, { month: 'Mês 2', kg: 28 }, { month: 'Mês 3', kg: 34 }] : period === '12 meses' ? [{ month: 'Dez', kg: 14 }, { month: 'Jan', kg: 18 }, { month: 'Fev', kg: 16 }, { month: 'Mar', kg: 23 }, { month: 'Abr', kg: 20 }, { month: 'Mai', kg: 18 }, { month: 'Jun', kg: 24 }, { month: 'Jul', kg: 21 }, { month: 'Ago', kg: 36 }, { month: 'Set', kg: 32 }, { month: 'Out', kg: 47 }, { month: 'Nov', kg: 39 }] : monthlyImpact;
  const exportReport = () => { const rows = [['Data', 'Equipamento', 'Quantidade', 'Peso (kg)', 'Destinação', 'Status'], ...state.records.map(record => [record.date, record.equipment, String(record.quantity), record.weight.toFixed(1), record.destination, record.status])]; const csv = rows.map(row => row.map(value => `"${value.replaceAll('\"', '\"\"')}"`).join(';')).join('\n'); const blob = new Blob(['\ufeff', csv], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'novatech-impacto-demonstrativo.csv'; link.click(); URL.revokeObjectURL(url); };
  return <div className="impact-dashboard"><section className="impact-dashboard-hero"><div><Eyebrow icon={<Leaf size={14} />}>Seu impacto, acompanhado</Eyebrow><h2>Seu impacto vai muito<br />além do descarte.</h2><p>Indicadores demonstrativos para visualizar novas possibilidades.</p></div><div className="impact-score"><span>ECOSCORE</span><strong>78<small>/100</small></strong><div className="score-bars"><i /><i /><i /><i /><i /></div><small>Estimado com base em ações demonstrativas validadas.</small></div></section><section className="panel ecoscore-method"><div className="ecoscore-method-head"><span className="ecoscore-method-mark"><ShieldCheck size={17} /></span><div><span className="panel-eyebrow">CRITÉRIOS TRANSPARENTES</span><h2>Como interpretar o EcoScore.</h2></div><span className="demo-badge"><span className="demo-dot" />Exemplo demonstrativo</span></div><div className="ecoscore-criteria"><div><strong>40%</strong><span>registros de descarte validados</span></div><div><strong>25%</strong><span>diversidade de materiais destinados</span></div><div><strong>20%</strong><span>participação em campanhas</span></div><div><strong>15%</strong><span>consistência da jornada local</span></div></div><p>Pesos ilustrativos do protótipo, não um padrão de mercado ou medição ambiental oficial. Apenas registros validados entram no cálculo demonstrativo.</p></section><div className="period-tabs">{['7 dias', '30 dias', '90 dias', '6 meses', '12 meses'].map(p => <button className={p === period ? 'selected' : ''} key={p} onClick={() => setPeriod(p)}>{p}</button>)}</div><div className="metrics-grid impact-metrics"><MetricCard label="Resíduos destinados" value={`${totalKg} kg`} icon={<Recycle size={18} />} tone="orange" note="Inclui registros de exemplo" /><MetricCard label="Dispositivos" value="05" icon={<PackageCheck size={18} />} tone="blue" note="Histórico demonstrativo" /><MetricCard label="CO₂ equivalente" value="6,4 kg" icon={<Leaf size={18} />} tone="green" note="Estimativa ilustrativa, não científica" /><MetricCard label="Campanhas" value="03" icon={<Sparkles size={18} />} tone="dark" note="Participações demonstrativas" /></div><div className="impact-chart-grid"><section className="panel impact-line-panel"><div className="panel-head"><div><span className="panel-eyebrow">EVOLUÇÃO</span><h2>Um novo ciclo a cada mês.</h2></div><span className="chart-tag">{period}</span></div><div className="dashboard-chart impact-large-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData} margin={{ top: 12, right: 10, left: -18, bottom: 0 }}><defs><linearGradient id="impactArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#16A34A" stopOpacity={0.18} /><stop offset="95%" stopColor="#16A34A" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#eef0f3" strokeDasharray="4 4" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 11 }} dy={8} /><YAxis axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 10 }} tickFormatter={v => `${v} kg`} /><Tooltip formatter={v => [`${v} kg`, 'Destinados']} /><Area type="monotone" dataKey="kg" stroke="#16A34A" strokeWidth={2.4} fill="url(#impactArea)" /></AreaChart></ResponsiveContainer></div><div className="chart-footnote"><span className="footnote-green">●</span> Evolução mensal ilustrativa</div></section><section className="panel impact-bar-panel"><div className="panel-head"><div><span className="panel-eyebrow">POR CATEGORIA</span><h2>Materiais no ciclo</h2></div></div><div className="impact-bar-list">{[{ label: 'Informática', v: 42, color: '#F97316' }, { label: 'Celulares', v: 24, color: '#FDBA74' }, { label: 'Cabos', v: 18, color: '#16A34A' }, { label: 'Pilhas e baterias', v: 16, color: '#2563EB' }].map(x => <div className="impact-bar-row" key={x.label}><div><span>{x.label}</span><strong>{x.v}%</strong></div><div className="impact-bar"><span style={{ width: `${x.v}%`, background: x.color }} /></div></div>)}</div><div className="impact-target"><Target size={17} /><div><strong>Meta de participação</strong><span>25 kg · <b>12,8 kg</b> acumulados</span></div><div className="progress-track"><span style={{ width: '51%' }} /></div></div></section></div><div className="impact-map-grid"><section className="panel impact-map-card"><div className="panel-head"><div><span className="panel-eyebrow">MAPA OFICIAL DO GDF</span><h2>Visualização pública no Distrito Federal.</h2></div><DemoBadge /></div><MapPanel points={collectionPoints} selectedId={selectedMapId} className="impact-map"/><div className="chart-footnote">O mapa oficial do GDF é independente da lista fictícia de pontos da Grande São Paulo nesta demonstração.</div></section><section className="panel impact-region-panel"><span className="panel-eyebrow">PARTICIPAÇÃO POR REGIÃO</span><h2>Impacto em rede.</h2><p>Agregados fictícios para a demonstração.</p>{[['Pinheiros', '12,8 kg', '38%'], ['Paulista · Bela Vista', '8,4 kg', '26%'], ['Vila Madalena', '6,1 kg', '19%'], ['Outras regiões', '5,8 kg', '17%']].map((row, index) => <div className="impact-region-row" key={row[0]}><span className="impact-region-rank">0{index + 1}</span><span><strong>{row[0]}</strong><small>Participação demonstrativa</small></span><b>{row[1]}</b></div>)}<div className="impact-region-total"><Users size={14} /> Campanhas e participação são fictícias nesta versão.</div></section></div><section className="panel impact-history"><div className="panel-head"><div><span className="panel-eyebrow">HISTÓRICO DE DESTINAÇÃO</span><h2>Contribuições registradas.</h2></div><Button variant="outline" size="sm" onClick={exportReport}>Exportar CSV demonstrativo <ArrowUpRight size={13} /></Button></div><div className="table-scroll"><table className="data-table"><thead><tr><th>DATA</th><th>EQUIPAMENTO</th><th>QUANTIDADE</th><th>PESO</th><th>DESTINAÇÃO</th><th>STATUS</th></tr></thead><tbody>{state.records.map(r => <tr key={r.id}><td>{new Date(`${r.date}T12:00:00`).toLocaleDateString('pt-BR')}</td><td><strong>{r.equipment}</strong></td><td>{r.quantity}</td><td>{r.weight.toFixed(1)} kg</td><td>{r.destination}</td><td><StatusPill tone="green">{r.status}</StatusPill></td></tr>)}</tbody></table></div><div className="impact-transparency"><ShieldCheck size={16} /><span><strong>Transparência:</strong> registros, números, estimativas e evolução mostrados nesta versão são demonstrativos. A estimativa ambiental não equivale a medição científica oficial.</span></div></section></div>;
}

export function CampaignsPage() {
  const { state, createCampaign, toggleCampaignParticipation, updateCampaign, closeCampaign } = useStore();
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [ending, setEnding] = useState<Campaign | null>(null);
  const [filter, setFilter] = useState('Todas');
  const [name, setName] = useState('');
  const [organizer, setOrganizer] = useState(state.user?.name ?? 'Comunidade NovaTech');
  const [type, setType] = useState('Comunidade');
  const [goal, setGoal] = useState('100 kg');
  const [endDate, setEndDate] = useState(() => new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10));
  const [description, setDescription] = useState('');
  const joined = state.participatingCampaignIds;
  const canManage = ['admin', 'company', 'school'].includes(state.user?.role ?? '');
  const visibleCampaigns = state.campaigns.filter(campaign => filter === 'Todas' || (filter === 'Escolas' && campaign.type === 'Escola') || (filter === 'Empresas' && campaign.type === 'Empresa') || (filter === 'Comunidades' && ['Comunidade', 'Instituição'].includes(campaign.type)));
  const resetForm = () => { setName(''); setOrganizer(state.user?.name ?? 'Comunidade NovaTech'); setType('Comunidade'); setGoal('100 kg'); setEndDate(new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10)); setDescription(''); setEditingId(null); };
  const submit = (e: FormEvent) => { e.preventDefault(); if (name.trim().length < 3 || !goal.trim() || !endDate) return; const data = { name: name.trim(), organizer: organizer.trim() || 'Comunidade NovaTech', type, endDate, goal: goal.trim(), description: description.trim() || 'Campanha comunitária demonstrativa.' }; if (editingId) updateCampaign(editingId, data); else createCampaign(data); resetForm(); setOpen(false); };
  const edit = (campaign: Campaign) => { setEditingId(campaign.id); setName(campaign.name); setOrganizer(campaign.organizer); setType(campaign.type); setGoal(campaign.goal); setEndDate(campaign.endDate); setDescription(campaign.description); setOpen(true); };
  const create = () => { resetForm(); setOpen(true); };
  const participantCount = state.campaigns.reduce((sum, campaign) => sum + campaign.participants, 0);
  const collectedKg = state.campaigns.reduce((sum, campaign) => sum + (Number.parseFloat(campaign.collected) || 0), 0);
  return <div className="campaigns-page"><div className="campaign-banner"><div><Eyebrow icon={<SproutIcon />}>Uma comunidade em movimento</Eyebrow><h2>O impacto cresce quando<br /><em>fazemos juntos.</em></h2><p>Descubra iniciativas na sua região e participe de um novo ciclo coletivo.</p><Button onClick={create} variant="dark"><Plus size={15} />Criar campanha</Button></div><div className="campaign-banner-art"><div className="campaign-art-circle"><Leaf size={30} /></div><span className="campaign-stamp">IMPACTO<br /><strong>COLETIVO</strong></span><span className="campaign-art-dot dot-1" /><span className="campaign-art-dot dot-2" /></div></div><div className="campaign-stats"><div><span>Campanhas ativas</span><strong>{state.campaigns.filter(c => c.status === 'Em andamento').length.toString().padStart(2, '0')}</strong></div><div><span>Participantes</span><strong>{participantCount.toLocaleString('pt-BR')}</strong><small>Indicador demonstrativo</small></div><div><span>Arrecadado</span><strong>{collectedKg.toLocaleString('pt-BR')} <small>kg</small></strong><small>Valor ilustrativo</small></div><div><span>Impacto em rede</span><strong><Leaf size={22} /></strong></div></div><div className="campaign-section-head"><div><span className="panel-eyebrow">CAMPANHAS EM DESTAQUE</span><h2>Escolha uma causa para apoiar.</h2></div><div className="campaign-tabs">{['Todas', 'Escolas', 'Empresas', 'Comunidades'].map(tab => <button className={filter === tab ? 'selected' : ''} key={tab} onClick={() => setFilter(tab)}>{tab}</button>)}</div></div><div className="campaign-grid">{visibleCampaigns.map((campaign, i) => { const isJoined = joined.includes(campaign.id); const collected = Number.parseFloat(campaign.collected) || 0; const target = Number.parseFloat(campaign.goal) || 0; const progress = target ? Math.min(100, collected / target * 100) : 0; return <article className="campaign-card" key={campaign.id}><div className={`campaign-art campaign-art-${i % 3}`}><span className="campaign-type">{campaign.type}</span><span className="campaign-art-label">NOVO<br />CICLO</span><span className="campaign-art-icon">{i % 3 === 0 ? <Recycle size={23} /> : i % 3 === 1 ? <GraduationCapIcon /> : <BuildingIcon />}</span></div><div className="campaign-card-body"><div className="campaign-card-organizer"><span>{campaign.organizer}</span><StatusPill tone={campaign.status === 'Em andamento' ? 'green' : 'neutral'}>{campaign.status}</StatusPill></div><h3>{campaign.name}</h3><p>{campaign.description}</p><div className="campaign-progress-label"><span>Arrecadação demonstrativa</span><strong>{campaign.collected} <small>de {campaign.goal}</small></strong></div><div className="progress-track"><span style={{ width: `${progress}%` }} /></div><div className="campaign-card-foot"><span><UsersSmall />{campaign.participants} participantes</span><button disabled={campaign.status !== 'Em andamento'} className={isJoined ? 'joined' : ''} onClick={() => toggleCampaignParticipation(campaign.id)}>{isJoined ? <><Check size={13} />Participando</> : <>Participar <ArrowRight size={13} /></>}</button></div>{canManage && <div className="campaign-manage-row"><button onClick={() => edit(campaign)}><Pencil size={12} />Editar</button>{campaign.status === 'Em andamento' && <button onClick={() => setEnding(campaign)}><X size={12} />Encerrar</button>}</div>}</div></article>; })}{visibleCampaigns.length === 0 && <div className="empty-state"><SproutIcon /><strong>Nenhuma campanha nesta categoria.</strong></div>}</div><div className="inline-demo-note"><ShieldCheck size={14} />Participações, campanhas, contagens e arrecadação são demonstrativas e ficam apenas neste navegador.</div><Modal open={open} onClose={() => { setOpen(false); resetForm(); }} title={editingId ? 'Editar campanha demonstrativa' : 'Criar campanha demonstrativa'}><form className="campaign-form" onSubmit={submit}><label className="form-label">Nome da campanha<input className="form-control" value={name} onChange={e => setName(e.target.value)} placeholder="Ex.: Semana do Reuso Digital" minLength={3} required /></label><div className="form-grid"><label className="form-label">Organizador<input className="form-control" value={organizer} onChange={e => setOrganizer(e.target.value)} /></label><label className="form-label">Tipo<select className="form-control" value={type} onChange={e => setType(e.target.value)}><option>Comunidade</option><option>Escola</option><option>Empresa</option><option>Instituição</option></select></label></div><div className="form-grid"><label className="form-label">Meta de arrecadação<input className="form-control" value={goal} onChange={e => setGoal(e.target.value)} required /></label><label className="form-label">Encerramento<input className="form-control" type="date" min={new Date().toISOString().slice(0, 10)} value={endDate} onChange={e => setEndDate(e.target.value)} required /></label></div><label className="form-label">Descrição<textarea className="form-control" rows={3} value={description} onChange={e => setDescription(e.target.value)} placeholder="Conte o objetivo da campanha" /></label><div className="form-error-message"><ShieldCheck size={14} />Campanha de demonstração local, sem divulgação pública.</div><Button type="submit">{editingId ? 'Salvar alterações' : 'Criar campanha'} <ArrowRight size={14} /></Button></form></Modal><Modal open={!!ending} onClose={() => setEnding(null)} title="Encerrar campanha demonstrativa"><p>Encerrar “{ending?.name}” impede novas participações nesta demonstração. Os dados ficam guardados neste navegador.</p><div className="modal-actions"><Button variant="secondary" onClick={() => setEnding(null)}>Manter ativa</Button><Button onClick={() => { if (ending) closeCampaign(ending.id); setEnding(null); }}>Encerrar campanha <Check size={14} /></Button></div></Modal></div>;
}
function SproutIcon() { return <Leaf size={14} />; }
function GraduationCapIcon() { return <Sparkles size={21} />; }
function BuildingIcon() { return <Building2Icon />; }
function Building2Icon() { return <PackageCheck size={20} />; }
function UsersSmall() { return <span className="users-small">◉</span>; }

export function NotificationsPage() {
  const { state, markRead, markAllRead } = useStore();
  const [filter, setFilter] = useState('Todas');
  const notifications = state.notifications.filter(n => filter === 'Todas' || (filter === 'Não lidas' ? !n.read : n.read));
  const iconFor = (icon: string) => icon === 'calendar' ? <CalendarDays size={16} /> : icon === 'megaphone' ? <SproutIcon /> : icon === 'gift' ? <Gift size={16} /> : icon === 'trophy' ? <Award size={16} /> : <Bell size={16} />;
  return <div className="notifications-page"><div className="page-section-toolbar"><div><h2>Uma pequena atualização.</h2><p>Acompanhe o que está acontecendo na sua jornada.</p></div><Button variant="outline" onClick={markAllRead}><Check size={14} />Marcar todas como lidas</Button></div><div className="notification-tabs">{['Todas', 'Não lidas', 'Lidas'].map(x => <button key={x} onClick={() => setFilter(x)} className={filter === x ? 'selected' : ''}>{x}{x === 'Não lidas' && <span>{state.notifications.filter(n => !n.read).length}</span>}</button>)}</div><div className="notification-list">{notifications.map(n => <button className={`notification-row ${n.read ? 'notification-read' : ''}`} key={n.id} onClick={() => markRead(n.id)}><span className={`notification-row-icon notification-${n.icon}`}>{iconFor(n.icon)}</span><span className="notification-row-copy"><strong>{n.title}</strong><span>{n.detail}</span><small>{n.date} · Demonstração</small></span>{!n.read && <span className="notification-unread-dot" />}{n.read && <CheckCircle2 size={16} className="notification-check" />}</button>)}{notifications.length === 0 && <div className="empty-state"><Bell size={22} /><strong>Nenhuma notificação nesta categoria.</strong></div>}</div><div className="inline-demo-note"><ShieldCheck size={14} />Notificações de exemplo; não correspondem a eventos externos reais.</div></div>;
}

export function ProfilePage() {
  const { state, updateProfile } = useStore();
  const user = state.user!;
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(user.name);
  const [city, setCity] = useState(user.city);
  const [saved, setSaved] = useState(false);
  const roleText: Record<UserRole, string> = { citizen: 'Pessoa física', company: 'Empresa', school: 'Escola', collector: 'Ponto de coleta', admin: 'Administrador demonstrativo' };
  const save = (e: React.FormEvent) => { e.preventDefault(); updateProfile({ name, city }); setEditing(false); setSaved(true); window.setTimeout(() => setSaved(false), 3000); };
  return <div className="profile-page"><section className="profile-cover"><div className="profile-cover-shape shape-one" /><div className="profile-cover-shape shape-two" /><span className="profile-cover-tag"><Leaf size={13} />SUA JORNADA ECO</span></section><section className="panel profile-card"><div className="profile-card-head"><div className="profile-avatar">{user.name.split(' ').slice(0, 2).map(x => x[0]).join('')}</div><div><h2>{user.name}</h2><p>{user.email}</p></div><Button variant="outline" onClick={() => { setName(user.name); setCity(user.city); setEditing(v => !v); }}><UserRound size={14} />{editing ? 'Fechar edição' : 'Editar perfil'}</Button></div>{saved && <SuccessLine>Alterações salvas neste navegador.</SuccessLine>}{editing ? <form className="profile-edit-form" onSubmit={save}><label className="form-label">Nome<input className="form-control" value={name} onChange={e => setName(e.target.value)} required /></label><label className="form-label">Cidade<input className="form-control" value={city} onChange={e => setCity(e.target.value)} required /></label><div className="profile-edit-actions"><Button type="submit">Salvar alterações <Check size={14} /></Button></div></form> : <div className="profile-info-grid"><div><span>Tipo de usuário</span><strong>{roleText[user.role]}</strong></div><div><span>Cidade</span><strong>{user.city}</strong></div><div><span>Participante desde</span><strong>{user.joinedAt}</strong></div><div><span>EcoScore demonstrativo</span><strong>78 / 100</strong></div></div>}<div className="profile-settings"><h3>Preferências</h3>{[['Notificações', 'Atualizações locais sobre sua jornada.', <Bell size={16} />], ['Privacidade', 'Seus dados de demonstração ficam neste navegador.', <ShieldCheck size={16} />], ['Dados locais', 'Limpar informações salvas requer uso das configurações do navegador.', <SlidersHorizontal size={16} />]].map(([title, detail, icon]) => <div className="setting-row" key={String(title)}><span className="setting-icon">{icon}</span><span><strong>{title}</strong><small>{detail}</small></span><ChevronRight size={15} /></div>)}</div></section><div className="inline-demo-note"><ShieldCheck size={14} />Este perfil é fictício/demonstrativo. Não há conta remota nem armazenamento seguro.</div></div>;
}

export function OrganizationPage({ kind }: { kind: 'company' | 'school' }) {
  const { state } = useStore();
  const school = kind === 'school';
  const requiredRole: UserRole = school ? 'school' : 'company';
  if (!state.user || state.user.role !== requiredRole) return <div className="admin-denied"><span><ShieldCheck size={25} /></span><Eyebrow>Espaço institucional</Eyebrow><h2>A área é específica para {school ? 'escolas' : 'empresas'}.</h2><p>Seu perfil atual é {state.user ? 'outro tipo de participante' : 'visitante'}. Entre novamente na demonstração e escolha o perfil {school ? 'Escola' : 'Empresa'} para consultar este painel.</p><Button to="/login" variant="dark">Trocar perfil demonstrativo <ArrowRight size={14} /></Button></div>;
  const cards = school ? [['Resíduos destinados', '92 kg', 'Exemplo'], ['Participantes', '124', 'Dados demonstrativos'], ['Turmas inscritas', '06', 'Sem dados pessoais'], ['Campanhas ativas', '02', 'Em andamento']] : [['Resíduos destinados', '318 kg', 'Exemplo'], ['Dispositivos', '148', 'Registros demonstrativos'], ['Participantes', '205', 'Dados ilustrativos'], ['Campanhas ativas', '03', 'Em andamento']];
  return <div className="org-dashboard"><section className={`org-dashboard-banner ${school ? 'org-dashboard-school' : ''}`}><div><Eyebrow icon={school ? <Sparkles size={14} /> : <Building2 size={14} />}>{school ? 'Aprender, participar, transformar' : 'Gestão de sustentabilidade'}</Eyebrow><h2>{school ? 'Uma escola mais circular começa com uma ideia.' : 'Sustentabilidade com clareza, do início ao impacto.'}</h2><p>{school ? 'Organize campanhas e acompanhe resultados coletivos sem expor dados pessoais de estudantes.' : 'Acompanhe indicadores demonstrativos e organize iniciativas de destinação responsável.'}</p><Button to="/app/campanhas" variant={school ? 'outline' : 'dark'}>Gerenciar campanhas <ArrowRight size={14} /></Button></div><div className="org-badge-graphic"><span>{school ? <GraduationCapIcon /> : <Building2Icon />}</span><small>{school ? 'EDUCAÇÃO' : 'CIRCULARIDADE'}</small></div></section><div className="metrics-grid org-metrics">{cards.map((item, i) => <MetricCard key={item[0]} label={item[0]} value={item[1]} icon={i === 0 ? <Recycle size={18} /> : i === 1 ? <Users size={18} /> : i === 2 ? <Target size={18} /> : <Sparkles size={18} />} tone={['orange', 'green', 'blue', 'dark'][i] as 'orange' | 'green' | 'blue' | 'dark'} note={item[2]} />)}</div><div className="org-dashboard-grid"><section className="panel org-campaign-panel"><div className="panel-head"><div><span className="panel-eyebrow">CAMPANHAS {school ? 'ESCOLARES' : 'DA ORGANIZAÇÃO'}</span><h2>Projetos em andamento.</h2></div><Button to="/app/campanhas" size="sm"><Plus size={14} />Nova campanha</Button></div>{state.campaigns.slice(0, 3).map((campaign, i) => <div className="org-campaign-row" key={campaign.id}><span className={`org-campaign-icon org-campaign-icon-${i}`}><Recycle size={16} /></span><span><strong>{campaign.name}</strong><small>{campaign.organizer} · termina {new Date(`${campaign.endDate}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' })}</small></span><span className="org-campaign-progress"><b>{campaign.collected}</b><small>de {campaign.goal}</small></span><ChevronRight size={15} /></div>)}</section><section className="panel org-goal-panel"><span className="panel-eyebrow">META DO CICLO</span><h2>{school ? 'Turma mais sustentável' : 'Resíduos em destinação correta'}</h2><p>{school ? 'Meta coletiva para esta etapa da campanha.' : 'Acompanhe a evolução da meta demonstrativa.'}</p><div className="org-goal-number"><strong>{school ? '92' : '318'} <small>kg</small></strong><span>de {school ? '120' : '500'} kg</span></div><div className="progress-track"><span style={{ width: school ? '76%' : '64%' }} /></div><div className="org-goal-foot"><span><Target size={14} />{school ? '76% da meta' : '64% da meta'}</span><span>Exemplo</span></div><Button to="/app/impacto" variant="ghost" size="sm">Ver relatório de impacto <ArrowRight size={14} /></Button></section></div><div className="inline-demo-note"><ShieldCheck size={14} />Painel institucional demonstrativo. Métricas e campanhas são exemplos, não relatórios certificados.</div></div>;
}
